#include "solvers/wave3d.hpp"
#include "solvers/run_options.hpp"
#include <navier/storage/dataset_store.hpp>
#include <sstream>
int main(int argc,char** argv){try{auto run=navier::examples::options(argc,argv,"wave3d-v2.data");if(argc<3)run.side=32;if(argc<4)run.steps=120;if(argc<5)run.interval=10;navier::examples::Wave3D solver(run.side);std::ostringstream meta;meta.precision(17);meta<<"{\"schema_version\":1,\"solver\":\"wave3d-forced-fdm\",\"numerical_method\":\"second-order centered space/time\",\"boundary\":\"dirichlet\",\"parameters\":{\"wave_speed\":"<<solver.wave_speed()<<",\"dt\":"<<solver.dt()<<",\"dx\":1,\"source\":\"Gaussian-modulated sinusoidal point forcing\"}}";navier::storage::DatasetStore store(run.path,{.create=true,.metadata=meta.str()});const auto cells=run.side*run.side*run.side;const auto save=[&](std::uint64_t step){const auto data=solver.values();const std::span<const double> values(data);const std::vector<std::uint64_t> shape{run.side,run.side,run.side};const std::array<navier::storage::FieldView,2> fields{{{{"amplitude",navier::storage::ScalarType::float64,shape,"normalized"},values.first(cells)},{{"energy_density",navier::storage::ScalarType::float64,shape,"normalized"},values.subspan(cells)}}};const std::array<navier::storage::Metric,2> metrics{{{"total_energy",solver.total_energy(),"normalized"},{"max_amplitude",solver.max_amplitude(),"normalized"}}};store.save(step,static_cast<double>(step)*solver.dt(),fields,metrics,navier::storage::CheckpointKind::analysis);};save(0);for(std::uint64_t step=1;step<=run.steps;++step){solver.advance();if(step%run.interval==0||step==run.steps)save(step);}std::cout<<"NAVIER02 Wave3D: "<<store.size()<<" analysis checkpoints in "<<run.path.string()<<'\n';return 0;}catch(const std::exception& error){std::cerr<<"Wave3D v2: "<<error.what()<<'\n';return 1;}}
